import copy
out = copy.deepcopy(grid)
# Connect aligned 2s by filling all cells between outermost markers along each row and column.
for r,row in enumerate(grid):
    cs=[c for c,v in enumerate(row) if v==2]
    if len(cs)>=2:
        for c in range(min(cs)+1,max(cs)):
            if out[r][c]==0: out[r][c]=3
for c in range(len(grid[0])):
    rs=[r for r in range(len(grid)) if grid[r][c]==2]
    if len(rs)>=2:
        for r in range(min(rs)+1,max(rs)):
            if out[r][c]==0: out[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in out))
print('markers',sum(v==2 for row in grid for v in row),'fills',sum(v==3 for row in out for v in row))

