# 4-connected component labels of 2s; connect only gaps between distinct components.
R,C=len(grid),len(grid[0]); labels=[[-1]*C for _ in range(R)]; comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==2 and labels[r][c]<0:
   k=len(comps); stack=[(r,c)]; labels[r][c]=k; cells=[]
   while stack:
    a,b=stack.pop(); cells.append((a,b))
    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
     x,y=a+da,b+db
     if 0<=x<R and 0<=y<C and grid[x][y]==2 and labels[x][y]<0:
      labels[x][y]=k;stack.append((x,y))
   comps.append(cells)
